import { GENRES } from '../data/genres'
import { useCatalog } from '../lib/catalog-context'
import Cover from '../components/Cover'
import { navigate } from '../lib/router'
import { formatViews, genreHref } from '../lib/utils'

export default function Genres() {
  const { series: catalog, loading } = useCatalog()

  return (
    <main className="mx-auto max-w-[1240px] animate-fade-up px-4 py-10 sm:px-6 lg:px-8">
      <div className="mb-8">
        <div className="eyebrow mb-2 text-accent">Genre Index</div>
        <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">Genre Directory</h1>
        <p className="mt-2 max-w-xl text-ink-soft">
          Browse every genre category on the platform — from court fantasy to deep-space
          horror.
        </p>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {GENRES.map((g) => {
          const series = catalog.filter((s) => s.genres.includes(g.name))
          const views = series.reduce((n, s) => n + s.views, 0)
          const sample = series[0]
          return (
            <a
              key={g.name}
              href={genreHref(g.name)}
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate(genreHref(g.name))
              }}
              className="group relative overflow-hidden rounded-[16px] border border-line bg-paper transition-all hover:-translate-y-1 hover:shadow-lg"
            >
              {/* Tinted header strip from the genre's sample series palette */}
              <div
                className="relative h-20"
                style={{
                  background: sample
                    ? `linear-gradient(120deg, hsl(${sample.hue} 32% 16%) 0%, hsl(${sample.accentHue} 36% 28%) 100%)`
                    : '#181817',
                }}
              >
                <div className="absolute inset-0 flex items-center gap-2 px-4">
                  {loading
                    ? Array.from({ length: 5 }).map((_, i) => (
                        <div key={i} className="h-12 w-9 animate-pulse rounded-md bg-white/10" />
                      ))
                    : series.slice(0, 5).map((s) => (
                        <div
                          key={s.id}
                          className="h-12 w-9 overflow-hidden rounded-md opacity-90 ring-1 ring-white/20 transition-transform duration-300 group-hover:-translate-y-1"
                          style={{ transform: `rotate(${(series.indexOf(s) - 2) * 3}deg)` }}
                        >
                          <Cover series={s} showTitle={false} rounded="rounded-md" />
                        </div>
                      ))}
                </div>
              </div>
              <div className="p-5">
                <div className="flex items-baseline justify-between gap-2">
                  <h3 className="text-lg font-extrabold tracking-tight transition-colors group-hover:text-accent">
                    {g.name}
                  </h3>
                  <span className="text-xs font-bold text-ink-faint">
                    {loading ? '…' : `${series.length} ${series.length === 1 ? 'title' : 'titles'}`}
                  </span>
                </div>
                <p className="mt-1.5 line-clamp-2 text-sm leading-snug text-ink-soft">
                  {g.tagline}
                </p>
                <div className="mt-3 flex items-center justify-between text-xs text-ink-faint">
                  <span>{loading ? '' : `${formatViews(views)} total views`}</span>
                  <span className="font-bold text-accent opacity-0 transition-opacity group-hover:opacity-100">
                    Explore Genre →
                  </span>
                </div>
              </div>
            </a>
          )
        })}
      </div>
    </main>
  )
}
